Ext.define('BNK.view.Budget.bgx.com.BgxComScrp01MViewController', {
    extend: 'BaseViewController',
    alias: 'controller.BgxComScrp01MViewController',

    config: {
        viewId: 'BgxComScrp01M'
    },

    /* 조회 */
    onSelect: function() {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            data = vm.get('initData'),
            params = {
                aplEmpId : data.aplEmpId,
                dlngYn : data.dlngYn,	// 처리여부
                fndcYn : data.fndcYn,	// 마감일자 체크여부
                onlyScrpTab : 'card'
            },
            store = vm.storeInfo.ApvlStore,
            dateCnt = refs.date_container,
            dateCntCtrl = dateCnt.controller,
            strdt = dateCnt.refs.strdt,
            edt = dateCnt.refs.edt,
            cdno = refs.txtCardNo,
            mcnm = refs.txtMcNm;

        // 조회기간
        var result = dateCntCtrl.dateValid();
        if (result != '') {
            Ext.Msg.alert('알림', result);
            return;
        } else {
            if (strdt.getValue() < data.strdt || edt.getValue() > data.edt) {
                // [이가영] : bsnsYy년의 1월 1일 부터 12월 31일까지만 신청가능하도록 해야한다.
                me.showAlert(DateUtils.parseDate(data.strdt) + ' ~ ' + DateUtils.parseDate(data.edt) + ' 사이만 조회가능합니다.');
                strdt.setValue(data.strdt);
                edt.setValue(data.edt);
                me.onSelect();
                return;
            }

            params.apvlStrdt = Ext.Date.format(strdt.getValue(), 'Ymd');
            params.apvlEdt = Ext.Date.format(edt.getValue(), 'Ymd');
        }

        // 카드번호
        if (cdno && cdno.getValue()) {
            params.cdno = cdno.getValue();
        }

        // 상호
        if (mcnm && mcnm.getValue()) {
            params.mcNm = mcnm.getValue();
        }

        store.getProxy().extraParams = params;
        store.removeAll();
        store.loadPage(1);
    },

    showAlert: function(msg) {
        Ext.Msg.show({
                buttons :  {
                    yes : {itemId : Ext.MessageBox.YES, text : '확인'}
                },
                title : '알림',
                message : msg,
                alwaysOnTop : true,
                fn : function(btn) {
                    return;
                }
            });
    },

    /* 승인내역선택 -> 작성화면 (단건) */
    onGridSelect: function(dataview, selected, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            ctrl = me.view.parent.parent.controller,
            fndcDt = vm.get('initData.fndcDt'),
            record = selected[0].data;

        if (record.apvlDt <= fndcDt) {
            // 마감일자 체크
            //     Ext.Msg.show({
            //         buttons :  {
            //             yes : {itemId : Ext.MessageBox.YES, text : '확인'}
            //         },
            //         title : '알림',
            //         message :  Messages.getMessage('E8029',[record.mcNm,DateUtils.parseDate(vm.get('initData.fndcDt'))]),
            //         alwaysOnTop : true,
            //         maxWidth : '95%',
            //         fn : function(btn) {
            //             return;
            //         }
            //     });
            me.showAlert(Messages.getMessage('E8029',[record.mcNm,DateUtils.parseDate(vm.get('initData.fndcDt'))]));
        } else if (record.apvlDt < 20200701) {
            /* 20.07.01 예산오픈으로 인한 분기처리 */
            //     Ext.Msg.show({
            //         buttons :  {
            //             yes : {itemId : Ext.MessageBox.YES, text : '확인'}
            //         },
            //         title : '알림',
            //         message :  '2020-07-01 이전은 [경비노트]-[법인카드] 메뉴를 이용바랍니다.',
            //         alwaysOnTop : true,
            //         maxWidth : '95%',
            //         fn : function(btn) {
            //             return;
            //         }
            //     });
            me.showAlert('2020-07-01 이전은 [경비노트]-[법인카드] 메뉴를 이용바랍니다.');
        } else {
            ctrl.getViewModel().set('record', record);
            refs.grid.getStore().removeAll();
            ctrl.fnConfirm();
        }
    },

    /* 초기화 */
    onContainerInitialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            dateCnt = refs.date_container,
            strdt = dateCnt.refs.strdt,
            edt = dateCnt.refs.edt,
            date = new Date(),
            grid = refs.grid;

        grid.el.select('.x-headercontainer').setStyle('height',	'0px');

        vm.set('initData', component.config.data);	// 초기데이터

        // 조회기간
        edt.setValue(DateUtils.parseDate(date));
        date.setMonth(date.getMonth() - 1);
        date.setDate(1);
        strdt.setValue(DateUtils.parseDate(date));

        me.onSelect();
    },

    onStoreLoad: function(store, records, successful, operation, eOpts) {
        this.getReferences().grid.getScrollable().scrollTo('top', 0);		// 스크롤 보정
    }

});